/* The subject column carries the name, what it costs and what choosing it
 * does, stacked, so the header is the whole offer rather than a word. */
.comparison-subject {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-1);
}
.comparison-name {
  font-size: var(--font-base);
  font-weight: var(--font-weight-semibold);
  color: var(--foreground);
  text-transform: none;
  letter-spacing: normal;
}
.comparison-note { color: var(--muted-foreground); text-transform: none; letter-spacing: normal; }
.comparison-action { margin-block-start: var(--space-2); }

/* The one column the reader is pointed at, marked down its whole length rather
 * than on the header alone: the tick that matters is the one in the row being
 * read, twelve rows below the badge.
 *
 * --primary-soft, not --accent-soft: the accent wash is a NEUTRAL step (#ebf0f7)
 * within two percent of the page colour, so the recommended column read as the
 * page showing through the card (owner, 23.08: the background merges). A
 * recommendation is the brand pointing at something, and the brand wash is the
 * token that says so. */
.comparison-table .table-th[data-recommended],
.comparison-table .table-td[data-recommended] {
  background: var(--primary-soft);
  /* A GREY HAIRLINE DISAPPEARS ON A TINT. --border is mixed for the page and
   * the card, so on the brand wash the row rules simply stopped at the column
   * and started again after it, and the header had no line under it at all
   * (owner, 23.08: the borders are not visible on this background). The line
   * that separates rows in a tinted column has to be mixed from that tint. */
  border-block-end-color: color-mix(in oklch, var(--primary-soft), var(--foreground) 16%);
}

/* A tick, and the words behind it. Colour and shape are the shorthand; the
 * text is what a screen reader and a colour-blind reader actually get. */
.comparison-mark { display: inline-flex; min-block-size: var(--space-6); align-items: center; }
/* --success-soft-foreground, not --success-emphasis: the tick can land in a
 * cell that carries the success FILL (a comparison inside a toned column), and
 * the emphasis ink measures 4.29:1 on that fill in light and 3.75:1 in dark.
 * The soft-foreground role is the one designed to be read on it, and it is just
 * as readable on the card and on the recommended wash (handbook's contrast
 * gate, 23.08). */
.comparison-mark[data-included] { color: var(--success-soft-foreground); }

import './ComparisonTable.css'
import type { ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'
import { Table, TableScroll, THead, TBody, Tr, Th, Td } from '../Table'

export type ComparisonSubject = {
  key: string
  name: ReactNode
  /** The line under the name: a price, a term, a one-line summary. */
  note?: ReactNode
  /** The column the reader is being pointed at. One, or none. */
  recommended?: boolean
  /** What choosing this one does. Rendered under the column. */
  action?: ReactNode
}

export type ComparisonRow = {
  label: ReactNode
  /** One entry per subject key. `true` and `false` are rendered as a tick and
   *  a blank with the words behind them, so the column is not read by colour
   *  or by shape alone. */
  values: Record<string, ReactNode | boolean>
}

type Props = {
  label: string
  /** Hides the caption visually and KEEPS it for a screen reader. The caption is how a table
   *  announces what it is, so this hides it; it never removes it.
   */
  captionHidden?: boolean
  subjects: readonly ComparisonSubject[]
  rows: readonly ComparisonRow[]
  /** The header over the attribute column. */
  rowHeader?: ReactNode
  className?: string
}

/**
 * A few subjects as COLUMNS and their attributes as rows: plans, vendors,
 * candidates, options. The one table that transposes on purpose, because the
 * reader is comparing three things across twenty attributes rather than twenty
 * records across three fields.
 *
 * Many subjects turn the columns into a scroll nobody can hold in their head:
 * past about five, the subjects are records and belong in rows.
 *
 * Copy: row labels are the question each row answers, identical across subjects.
 * A row that changes its wording per column is not comparable.
 */
export function ComparisonTable({ label, captionHidden, subjects, rows, rowHeader, className }: Props) {
  const mark = (value: ReactNode | boolean) => {
    if (value === true) {
      return (
        <span className="comparison-mark" data-included="true">
          <Icon name="check" />
          <span className="sr-only">Included</span>
        </span>
      )
    }
    if (value === false) {
      /* Not a dash: a blank cell with the word behind it. A dash is read as a
       * value by a screen reader and as "unknown" by half of everyone else. */
      return <span className="comparison-mark"><span className="sr-only">Not included</span></span>
    }
    return value
  }

  return (
    <TableScroll label={label}>
      <Table caption={label} captionHidden={captionHidden} stickyHeader stickyColumn className={cn('comparison-table', className)}>
        <THead>
          <Tr>
            <Th scope="col">{rowHeader}</Th>
            {subjects.map((s) => (
              <Th key={s.key} scope="col" align="center" data-recommended={s.recommended || undefined}>
                <span className="comparison-subject">
                  <span className="comparison-name">{s.name}</span>
                  {s.note ? <span className="comparison-note">{s.note}</span> : null}
                  {s.action ? <span className="comparison-action">{s.action}</span> : null}
                </span>
              </Th>
            ))}
          </Tr>
        </THead>
        <TBody>
          {rows.map((row, i) => (
            <Tr key={i}>
              <Th scope="row">{row.label}</Th>
              {subjects.map((s) => (
                <Td key={s.key} align="center" data-recommended={s.recommended || undefined}>
                  {mark(row.values[s.key])}
                </Td>
              ))}
            </Tr>
          ))}
        </TBody>
      </Table>
    </TableScroll>
  )
}
